module reflect.target {
    exports target;   // widocznosc typow
    opens target;      // + DEEP REFLECTION
}

// BEZ 'opens target;': Field.setAccessible(true) -> InaccessibleObjectException
// Z 'opens target;': dziala poprawnie

module qual.api {
    exports qual to qual.friend; // TYLKO modul qual.friend widzi pakiet 'qual'
}

// kazdy INNY modul (nawet jesli 'requires qual.api') dostaje
// DOKLADNIE taki sam blad kompilacji jak przy braku exports w ogole

// BLAD: exports bez opens, Hibernate nie moze wypelnic prywatnych pol
module myapp {
    exports com.example.entities; // widocznosc typow OK
    // BRAK opens com.example.entities; - deep reflection ZABLOKOWANA
}

// Hibernate: field.setAccessible(true); // InaccessibleObjectException!

// POPRAWNIE: exports + opens dla pakietu z encjami
module myapp {
    exports com.example.entities;
    opens com.example.entities; // Hibernate/Jackson moga uzywac refleksji
}

